export type SlotMachineProps = Record<string, any>;

const SlotMachine: React.FC<SlotMachineProps> = ({
  backgroundColor = "#020617",
  transparentBackground = false,
  durationInSeconds = 10,
  machineAccentColor = "#d97706",
  jackpotText = "JACKPOT!",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const size = Math.min(width, height);

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Leverage pull down animation
  const leverPullFrame = 12;
  const leverRotation = interpolate(
    frame,
    [0, 6, 12, 18],
    [0, 45, 45, 0],
    {
      easing: Easing.bezier(0.25, 1, 0.5, 1),
      extrapolateRight: "clamp",
    }
  );

  // Reel Stop Timings (Locked Left-to-Right)
  // Spin starts after lever is fully pulled (frame 15)
  const spinStart = 15;
  const stopTimings = [
    { start: spinStart, end: 70 },  // Reel 1
    { start: spinStart, end: 110 }, // Reel 2
    { start: spinStart, end: 150 }, // Reel 3
  ];

  const jackpotFrame = stopTimings[2].end;

  // Spin rotation offset calculations
  const getReelYOffset = (index: number) => {
    const { start, end } = stopTimings[index];
    if (frame < start) return 0;

    // We interpolate the continuous spin rotation
    // Slowing down dynamically via a custom cubic bezier or ease-out
    const progress = interpolate(frame, [start, end], [0, 1], {
      easing: Easing.bezier(0.12, 0.85, 0.3, 1),
      extrapolateRight: "clamp",
    });

    // Each spin progress drives multiple complete rotations of the icons strip.
    // The strip has 7 elements. The middle one (index 3) is the Golden Poker Chip.
    // We want the final offset to align perfectly on the Golden Poker Chip (which is centered).
    // Adding 3 * itemHeight ensures it stops exactly on the Golden Poker Chip (index 3).
    const rotations = 6 + index * 3; 
    const itemHeight = size * 0.18; // proportional height of each slot item
    const totalDistance = rotations * ICONS_LIST.length * itemHeight + 3 * itemHeight;

    return progress * totalDistance;
  };

  // Calculating bounce on lock
  const getReelBounce = (index: number) => {
    const { end } = stopTimings[index];
    if (frame < end) return 1;
    const lockSpring = spring({
      frame: frame - end,
      fps,
      config: { damping: 12, mass: 0.5, stiffness: 120 },
    });
    return interpolate(lockSpring, [0, 1], [0.95, 1]);
  };

  // Jackpot Glow & Rays Trigger (once last wheel locks)
  const jackpotProgress = spring({
    frame: Math.max(0, frame - jackpotFrame),
    fps,
    config: { damping: 15, stiffness: 80 },
  });

  const glowOpacity = interpolate(jackpotProgress, [0, 1], [0, 1]);
  const raysScale = interpolate(jackpotProgress, [0, 1], [0.2, 1], {
    easing: Easing.out(Easing.cubic),
  });

  // Generated dynamic background rays for Jackpot celebration
  const rays = Array.from({ length: 18 }).map((_, i) => {
    const angle = (i * 360) / 18;
    return (
      <line
        key={i}
        x1="50%"
        y1="50%"
        x2="50%"
        y2="-100%"
        stroke="#fbbf24"
        strokeWidth="6"
        strokeLinecap="round"
        opacity={glowOpacity * 0.7}
        style={{
          transformOrigin: "center center",
          transform: `rotate(${angle}deg) scaleY(${raysScale})`,
          mixBlendMode: "screen",
          transition: "none",
        }}
      />
    );
  });

  // Render individual Reels
  const renderReel = (reelIndex: number) => {
    const yOffset = getReelYOffset(reelIndex);
    const scaleY = getReelBounce(reelIndex);

    const itemHeight = size * 0.18;

    // Create a wrapping repeating strip of items to simulate infinite loop
    const visibleItems: React.ReactNode[] = [];
    const totalCycles = 24; 
    for (let cycle = 0; cycle < totalCycles; cycle++) {
      ICONS_LIST.forEach((icon, iconIndex) => {
        const isWinningChip = iconIndex === 3;
        visibleItems.push(
          <div
            key={`${cycle}-${iconIndex}`}
            style={{
              height: itemHeight,
              width: "100%",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              position: "relative",
              transition: "none",
            }}
          >
            {icon}
            {isWinningChip && (
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  borderRadius: "50%",
                  boxShadow: `0 0 45px 15px rgba(251, 191, 36, ${glowOpacity * 0.6})`,
                  opacity: glowOpacity,
                  mixBlendMode: "screen",
                  pointerEvents: "none",
                  transition: "none",
                }}
              />
            )}
          </div>
        );
      });
    }

    return (
      <div
        style={{
          width: "28%",
          height: "84%",
          backgroundColor: "#1e293b",
          borderRadius: size * 0.02,
          overflow: "hidden",
          position: "relative",
          boxShadow: "inset 0px 8px 24px rgba(0,0,0,0.8), inset 0px -8px 24px rgba(0,0,0,0.8)",
          border: "2px solid rgba(255,255,255,0.05)",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          transform: `scaleY(${scaleY})`,
          transition: "none",
        }}
      >
        <div
          style={{
            position: "absolute",
            width: "100%",
            display: "flex",
            flexDirection: "column",
            // The magic alignment so that when yOffset is 0, the Poker Chip (index 3) is perfectly centered in the window
            // Window is size * 0.38 tall (84% of 64% of size is ~size * 0.45). Half of window minus half of item height gives perfectly centered alignment.
            transform: `translateY(${-yOffset + (size * 0.38 - itemHeight) / 2}px)`,
            transition: "none",
          }}
        >
          {visibleItems}
        </div>
        {/* Shadow overlays on top and bottom of reels for depth */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            right: 0,
            height: "30%",
            background: "linear-gradient(to bottom, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0) 100%)",
            pointerEvents: "none",
            transition: "none",
          }}
        />
        <div
          style={{
            position: "absolute",
            bottom: 0,
            left: 0,
            right: 0,
            height: "30%",
            background: "linear-gradient(to top, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0) 100%)",
            pointerEvents: "none",
            transition: "none",
          }}
        />
      </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        overflow: "hidden",
      }}
    >
      {/* Background Jackpot Celebration Rays */}
      <div
        style={{
          position: "absolute",
          width: size * 1.5,
          height: size * 1.5,
          top: "10%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          pointerEvents: "none",
          zIndex: 1,
          transition: "none",
        }}
      >
        <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", overflow: "visible" }}>
          {rays}
        </svg>
      </div>

      {/* Main Container */}
      <div
        style={{
          position: "relative",
          width: size * 0.85,
          height: size * 0.56,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10,
          transition: "none",
        }}
      >
        {/* Physical Lever on Right Side */}
        <div
          style={{
            position: "absolute",
            right: -size * 0.12,
            top: "35%",
            width: size * 0.15,
            height: size * 0.3,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            transformOrigin: "left center",
            transform: `rotate(${leverRotation}deg)`,
            transition: "none",
            zIndex: 5,
          }}
        >
          {/* Lever Rod */}
          <div
            style={{
              width: size * 0.02,
              height: size * 0.2,
              background: "linear-gradient(90deg, #94a3b8 0%, #cbd5e1 50%, #475569 100%)",
              borderTopRightRadius: 4,
              borderTopLeftRadius: 4,
              boxShadow: "0px 4px 8px rgba(0,0,0,0.4)",
              transition: "none",
            }}
          />
          {/* Lever Handle Knob */}
          <div
            style={{
              width: size * 0.075,
              height: size * 0.075,
              borderRadius: "50%",
              marginTop: -size * 0.015,
              background: "radial-gradient(circle at 35% 35%, #fef08a 0%, #d97706 70%, #78350f 100%)",
              boxShadow: "0px 6px 12px rgba(0,0,0,0.5), inset -2px -2px 6px rgba(0,0,0,0.4)",
              transition: "none",
            }}
          />
        </div>

        {/* Machine Base Bracket Shadow */}
        <div
          style={{
            position: "absolute",
            inset: -4,
            backgroundColor: "#090d16",
            borderRadius: size * 0.05,
            boxShadow: "0 25px 50px -12px rgba(0, 0, 0, 0.9)",
            zIndex: -1,
            transition: "none",
          }}
        />

        {/* Sleek Minimalist Outer Metallic Frame */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            borderRadius: size * 0.045,
            background: "linear-gradient(135deg, #475569 0%, #0f172a 50%, #1e293b 100%)",
            border: `6px solid ${machineAccentColor}`,
            boxShadow: `0px 10px 30px rgba(0, 0, 0, 0.7), inset 0px 4px 12px rgba(255, 255, 255, 0.1), 0 0 20px ${glowOpacity * 0.5}px ${machineAccentColor}`,
            padding: size * 0.025,
            boxSizing: "border-box",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            zIndex: 8,
            transition: "none",
          }}
        >
          {/* Internal Inner Screen Border */}
          <div
            style={{
              width: "100%",
              height: "100%",
              backgroundColor: "#0b0f19",
              borderRadius: size * 0.03,
              display: "flex",
              justifyContent: "space-evenly",
              alignItems: "center",
              position: "relative",
              border: "3px solid #1e293b",
              boxSizing: "border-box",
              transition: "none",
            }}
          >
            {/* Play Line Guide Overlay */}
            <div
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                top: "50%",
                height: 4,
                background: `linear-gradient(90deg, rgba(251,191,36,0) 0%, rgba(251,191,36,${0.3 + glowOpacity * 0.7}) 50%, rgba(251,191,36,0) 100%)`,
                transform: "translateY(-50%)",
                zIndex: 20,
                pointerEvents: "none",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                padding: `0 ${size * 0.01}px`,
                boxSizing: "border-box",
                transition: "none",
              }}
            >
              {/* Play Line Side Triangles */}
              <div
                style={{
                  width: 0,
                  height: 0,
                  borderTop: "8px solid transparent",
                  borderBottom: "8px solid transparent",
                  borderLeft: `10px solid ${glowOpacity > 0.5 ? "#fbbf24" : "#e2e8f0"}`,
                  opacity: 0.8,
                  transition: "none",
                }}
              />
              <div
                style={{
                  width: 0,
                  height: 0,
                  borderTop: "8px solid transparent",
                  borderBottom: "8px solid transparent",
                  borderRight: `10px solid ${glowOpacity > 0.5 ? "#fbbf24" : "#e2e8f0"}`,
                  opacity: 0.8,
                  transition: "none",
                }}
              />
            </div>

            {/* Rendering the three Reels */}
            {renderReel(0)}
            {renderReel(1)}
            {renderReel(2)}
          </div>
        </div>
      </div>

      {/* Dynamic Jackpot Banner Text */}
      <div
        style={{
          marginTop: size * 0.08,
          height: size * 0.15,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 12,
          transition: "none",
        }}
      >
        <div
          style={{
            transform: `scale(${interpolate(jackpotProgress, [0, 0.7, 1], [0.5, 1.1, 1], { extrapolateRight: "clamp" })})`,
            opacity: glowOpacity,
            textAlign: "center",
            transition: "none",
          }}
        >
          <h1
            style={{
              margin: 0,
              fontSize: size * 0.075,
              fontWeight: 900,
              color: "#fbbf24",
              textTransform: "uppercase",
              letterSpacing: "4px",
              textShadow: "0 0 10px rgba(251, 191, 36, 0.6), 0 0 30px rgba(251, 191, 36, 0.4)",
              transition: "none",
            }}
          >
            {jackpotText}
          </h1>
          <p
            style={{
              margin: `${size * 0.01}px 0 0 0`,
              fontSize: size * 0.025,
              color: "#94a3b8",
              letterSpacing: "2px",
              transition: "none",
            }}
          >
            YOU HIT THREE CHIPS!
          </p>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SlotMachine;